<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { cambiarEstadoAfectacionPlanilla, guardarAfectacionPlanilla, listarAfectacionesPlanilla, listarOpcionesAfectacion } from '../services/afectacionesPlanilla'
import type { AfectacionPlanilla, AfectacionPlanillaPayload, CatalogoAfectacion } from '../interfaces/afectacionesPlanilla.interface'

type EstadoFiltro='todos'|'activo'|'inactivo'
const rows=ref<AfectacionPlanilla[]>([]),conceptos=ref<CatalogoAfectacion[]>([]),tipos=ref<CatalogoAfectacion[]>([]),criterio=ref(''),conceptoFiltro=ref<number|null>(null),tipoFiltro=ref<number|null>(null),estadoFiltro=ref<EstadoFiltro>('todos'),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<AfectacionPlanillaPayload>({concepto_id:null,tipo_afectacion_id:null,valor:null})
const message=(value:unknown)=>value instanceof Error?value.message:'No se pudo completar la operación.'
const filtered=computed(()=>{const search=criterio.value.trim().toLocaleLowerCase();return rows.value.filter(item=>{const text=`${item.concepto?.codigo??''} ${item.concepto?.descripcion??''} ${item.tipo_afectacion?.codigo??''} ${item.tipo_afectacion?.descripcion??''}`.toLocaleLowerCase();return (!search||text.includes(search))&&(conceptoFiltro.value===null||item.concepto_id===conceptoFiltro.value)&&(tipoFiltro.value===null||item.tipo_afectacion_id===tipoFiltro.value)&&(estadoFiltro.value==='todos'||item.estado===(estadoFiltro.value==='activo'))})})
const activeCount=computed(()=>rows.value.filter(item=>item.estado).length)
const selectedConcepto=computed(()=>conceptos.value.find(item=>item.id===form.concepto_id))
const selectedTipo=computed(()=>tipos.value.find(item=>item.id===form.tipo_afectacion_id))
const duplicate=computed(()=>form.concepto_id!==null&&form.tipo_afectacion_id!==null&&rows.value.some(item=>item.id!==editing.value&&item.concepto_id===form.concepto_id&&item.tipo_afectacion_id===form.tipo_afectacion_id))

async function load(){loading.value=true;error.value='';try{const [items,options]=await Promise.all([listarAfectacionesPlanilla(),listarOpcionesAfectacion()]);rows.value=items;conceptos.value=options.conceptos;tipos.value=options.tipos_afectacion}catch(value){error.value=message(value)}finally{loading.value=false}}
function open(item?:AfectacionPlanilla){editing.value=item?.id??null;Object.assign(form,item?{concepto_id:item.concepto_id,tipo_afectacion_id:item.tipo_afectacion_id,valor:item.valor===null?null:Number(item.valor)}:{concepto_id:null,tipo_afectacion_id:null,valor:null});error.value='';modal.value=true}
function validate(){if(form.concepto_id===null)return 'Debe seleccionar un concepto habilitado para EPS.';if(form.tipo_afectacion_id===null)return 'Debe seleccionar un tipo de afectación.';if(form.valor!==null&&(!Number.isFinite(form.valor)||form.valor<0||form.valor>999999.9999))return 'El valor debe estar entre 0 y 999,999.9999.';if(duplicate.value)return 'Ya existe una afectación para este concepto y tipo.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarAfectacionPlanilla(editing.value,{...form});modal.value=false;success.value=`Afectación ${editing.value?'actualizada':'registrada'} correctamente.`;await load()}catch(value){error.value=message(value)}finally{saving.value=false}}
async function toggle(item:AfectacionPlanilla){const action=item.estado?'desactivar':'restaurar';if(!confirm(`¿Desea ${action} esta afectación?`))return;try{const result=await cambiarEstadoAfectacionPlanilla(item.id);item.estado=result.estado;success.value=result.message??`Afectación ${item.estado?'restaurada':'desactivada'} correctamente.`}catch(value){error.value=message(value)}}
function clearFilters(){criterio.value='';conceptoFiltro.value=null;tipoFiltro.value=null;estadoFiltro.value='todos'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Afectaciones de planilla</nav><header class="hero"><div class="mark">AP</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Afectaciones de planilla EPS</h1><p>Relación de conceptos EPS con su impacto legal o tributario.</p></div><strong>{{filtered.length}} de {{rows.length}}</strong><button @click="open()">+ Nueva afectación</button></header><aside class="help"><b>Configuración EPS</b><span>Un concepto puede tener varias afectaciones. El valor opcional representa un factor, porcentaje o importe aplicable.</span></aside><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="stats"><div><b>{{rows.length}}</b><span>Total</span></div><div><b>{{conceptos.length}}</b><span>Conceptos EPS</span></div><div><b>{{activeCount}}</b><span>Activas</span></div><div><b>{{rows.length-activeCount}}</b><span>Inactivas</span></div></section><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Concepto o tipo"></label><label>Concepto<select v-model="conceptoFiltro"><option :value="null">Todos</option><option v-for="item in conceptos" :key="item.id" :value="item.id">{{item.codigo}} · {{item.descripcion}}</option></select></label><label>Tipo<select v-model="tipoFiltro"><option :value="null">Todos</option><option v-for="item in tipos" :key="item.id" :value="item.id">{{item.codigo}} · {{item.descripcion}}</option></select></label><label>Estado<select v-model="estadoFiltro"><option value="todos">Todos</option><option value="activo">Activas</option><option value="inactivo">Inactivas</option></select></label><button type="button" class="soft" @click="clearFilters">Limpiar</button></section><section class="table-card"><header><div><small>CONFIGURACIÓN LEGAL Y TRIBUTARIA</small><h2>Afectaciones registradas</h2></div></header><div v-if="loading" class="empty">Consultando afectaciones…</div><div v-else-if="!filtered.length" class="empty">No se encontraron afectaciones.</div><div v-else class="scroll"><table><thead><tr><th>Concepto EPS</th><th>Tipo de afectación</th><th>Valor</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><b>{{item.concepto?.codigo??`ID ${item.concepto_id}`}}</b><small>{{item.concepto?.descripcion??'Concepto no encontrado'}}</small></td><td><b>{{item.tipo_afectacion?.codigo??'—'}}</b><small>{{item.tipo_afectacion?.descripcion??'Tipo no encontrado'}}</small></td><td><span v-if="item.valor!==null" class="value">{{Number(item.valor).toFixed(4)}}</span><span v-else>—</span></td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button v-if="item.estado" class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Restaurar'}}</button></td></tr></tbody></table></div></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">AP</div><div><small>CONFIGURACIÓN EPS</small><h2>{{editing?'Editar':'Registrar'}} afectación</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Concepto EPS *<select v-model="form.concepto_id"><option :value="null">Seleccione un concepto</option><option v-for="item in conceptos" :key="item.id" :value="item.id">{{item.codigo}} · {{item.descripcion}}</option></select><small>Solo aparecen conceptos habilitados para EPS.</small></label><label>Tipo de afectación *<select v-model="form.tipo_afectacion_id"><option :value="null">Seleccione un tipo</option><option v-for="item in tipos" :key="item.id" :value="item.id">{{item.codigo}} · {{item.descripcion}}</option></select><small>Define el impacto legal o tributario.</small></label><label>Valor opcional<input v-model.number="form.valor" type="number" min="0" max="999999.9999" step="0.0001" placeholder="Ej. 0.0875"><small>Factor, porcentaje o importe; máximo 999,999.9999.</small></label><aside><b>Ejemplos</b><span>1.0000: factor unitario · 0.0875: 8.75% · 0.13: 13% · vacío: sin valor específico.</span></aside></div><p v-if="duplicate" class="conflict">Ya existe la combinación seleccionada.</p><div v-if="selectedConcepto&&selectedTipo" class="preview"><small>VISTA PREVIA</small><div><p><b>Concepto</b>{{selectedConcepto.codigo}} · {{selectedConcepto.descripcion}}</p><p><b>Tipo</b>{{selectedTipo.codigo}} · {{selectedTipo.descripcion}}</p><p><b>Valor</b>{{form.valor===null?'Sin valor':Number(form.valor).toFixed(4)}}</p></div></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving||duplicate">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>

<style scoped>
