overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:780px;border-collapse:collapse;font-size:.52rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}td small,td b{display:block}.active,.inactive,.value{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active,.value{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(820px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.dialog label small{margin-top:5px;color:#7e8a90;font-weight:400}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.grid aside{align-self:end;padding:9px;border-radius:7px;background:#f7f8f9;font-size:.48rem}.grid aside b,.grid aside span{display:block}.preview{margin-top:12px;padding:12px;border-radius:7px;background:#f2edff}.preview>div{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.preview p{margin:6px 0 0;font-size:.5rem}.preview p b{display:block}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:800px){.hero,.filters,.help{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%;min-width:0}.stats{grid-template-columns:repeat(2,1fr)}.grid,.preview>div{grid-template-columns:1fr}.actions{min-width:140px}}
</style>
